-- -----------------------------------------------------
-- Drop Schema ltt_result_input_tables if already exists and create new 
-- -----------------------------------------------------

DROP SCHEMA IF EXISTS LTT_RESULT_INPUT_TABLES ;

CREATE SCHEMA IF NOT EXISTS LTT_RESULT_INPUT_TABLES ;

-- -----------------------------------------------------
-- Use  `ltt_result_input_tables`
-- -----------------------------------------------------

#USE LTT_RESULT_INPUT_TABLES ;

-- -----------------------------------------------------
-- Table `ltt_result_input_tables`.`poduct_test_names`
-- -----------------------------------------------------
CREATE TABLE LTT_RESULT_INPUT_TABLES.PRODUCT_TEST_NAMES
(
    ID                      INT PRIMARY KEY AUTO_INCREMENT COMMENT 'Unique ID for the Table -->generated by  default',
    PRODUCT_NAME            VARCHAR (255) NOT NULL COMMENT 'Product Name i.e. eDCU_48V, eDCU_96V --> Hardcoded and should have import export option from GUI',
    TEST_NAME               VARCHAR (255) NOT NULL COMMENT 'Test Name like VIBRATION TEST, THERMAL ENDURANCE TEST -> Hardcoded and should have import export option from GUI',
    MISSION_PROFILE         VARCHAR (255) COMMENT 'Test Name like MISSION PROFILE 1, MISSION PROFILE 2 SHORT -> Hardcoded and should have import export option from GUI',
    CYCLE_DURATION	        INT COMMENT 'Test Duration of one cycle in seconds -> Hardcoded and should have import export option from GUI',
	NUMBER_OF_CYCLES        INT COMMENT 'Number of Test cycle needed to run -> Hardcoded and should have import export option from GUI',
    TOTAL_DURATION          INT	COMMENT 'Total Test Duration of one cycle in seconds -> Hardcoded and should have import export option from GUI'
) COMMENT 'This table will contain the Test related information for the products';

-- -----------------------------------------------------
-- Creating indexes in the PRODUCT_TEST_NAMES table to optimise the query time
-- -----------------------------------------------------
CREATE INDEX TEST_NAME_INDEX ON LTT_RESULT_INPUT_TABLES.PRODUCT_TEST_NAMES (TEST_NAME);
CREATE INDEX PRODUCT_NAME_INDEX ON LTT_RESULT_INPUT_TABLES.PRODUCT_TEST_NAMES (PRODUCT_NAME);

-- -----------------------------------------------------
-- Insert data in PRODUCT_TEST_NAMES table based on mission Profile`
-- -----------------------------------------------------
INSERT INTO LTT_RESULT_INPUT_TABLES.PRODUCT_TEST_NAMES (PRODUCT_NAME,TEST_NAME,MISSION_PROFILE,CYCLE_DURATION,NUMBER_OF_CYCLES,TOTAL_DURATION) VALUES 
