-- -----------------------------------------------------
-- Table `ltt_result_input_tables`.`fa_frame_details` Which is containing the Software Version informations
-- -----------------------------------------------------
CREATE TABLE LTT_RESULT_INPUT_TABLES.FA_FRAME_DETAILS
(
    ID                      INT PRIMARY KEY AUTO_INCREMENT COMMENT 'Unique ID for the Table -->generated by  default',
    SIGNAL_NAME          	VARCHAR (255) COMMENT 'Name of Signal in FE Frame  --> Hardcoded and should have import export option from GUI',
    OFFSET_NUM				INT COMMENT 'Start Byte of the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    NB_BYTES				INT	COMMENT 'Number of Bytes for the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    MASK_Hex				VARCHAR (255) COMMENT 'Mask need for the Signal like 0x01, 0x0F  --> Hardcoded and should have import export option from GUI'
    
) COMMENT 'This table will store the details of FA Frames';
-- -----------------------------------------------------
-- Table `ltt_result_input_tables`.`fe_frame_details`
-- -----------------------------------------------------
CREATE TABLE LTT_RESULT_INPUT_TABLES.FE_FRAME_DETAILS
(
    ID                      INT PRIMARY KEY AUTO_INCREMENT COMMENT 'Unique ID for the Table -->generated by  default',
    SIGNAL_NAME             VARCHAR (255) COMMENT 'Name of Signal in FE Frame  --> Hardcoded and should have import export option from GUI',
    OFFSET_NUM				INT COMMENT 'Start Byte of the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    NB_BYTES				INT	COMMENT 'Number of Bytes for the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    MASK_Hex 				VARCHAR (255) COMMENT 'Mask need for the Signal like 0x01, 0x0F  --> Hardcoded and should have import export option from GUI',
    SCALING_FACTOR		    FLOAT(6) COMMENT 'Conversion formula for the Signal ex. M in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    SCALING_OFFSET		    FLOAT(6) COMMENT 'Conversion formula for the Signal ex. C in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    UNIT					VARCHAR (255) COMMENT 'Unit of the Signal --> GUI - Non-editable combo box',
    VOLTAGE_DIVIDER_RATIO	FLOAT(6) COMMENT 'Conversion formula for the Signal ex. C in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    DEFAULT_VALUE			INT	COMMENT 'DEFAULT_VALUE of the Signal --> Hardcoded and should have import export option from GUI',
    DISPLAY_TYPE			VARCHAR (255) COMMENT 'DISPLAY_TYPE of the Signal --> Hardcoded and should have import export option from GUI'
) COMMENT 'This table will store the details of FE Frames';

-- -----------------------------------------------------
-- Table `ltt_result_input_tables`.`ff_frame_details`
-- -----------------------------------------------------
CREATE TABLE LTT_RESULT_INPUT_TABLES.FF_FRAME_DETAILS
(
    ID                      INT PRIMARY KEY AUTO_INCREMENT COMMENT 'Unique ID for the Table -->generated by  default',
    SIGNAL_NAME          	VARCHAR (255) COMMENT 'Name of Signal in FE Frame  --> Hardcoded and should have import export option from GUI',
    OFFSET_NUM				INT COMMENT 'Start Byte of the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    NB_BYTES				INT	COMMENT 'Number of Bytes for the Signal in Return Data --> Hardcoded and should have import export option from GUI',
    MASK_Hex				VARCHAR (255) COMMENT 'Mask need for the Signal like 0x01, 0x0F  --> Hardcoded and should have import export option from GUI',
    SCALING_FACTOR		    FLOAT(6)  COMMENT 'Conversion formula for the Signal ex. M in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    SCALING_OFFSET		    FLOAT(6)  COMMENT 'Conversion formula for the Signal ex. C in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    UNIT					VARCHAR (255) COMMENT 'Unit of the Signal -->  Hardcoded and should have import export option from GUI',
    VOLTAGE_DIVIDER_RATIO	FLOAT(6) COMMENT 'Conversion formula for the Signal ex. C in  Mx+C, optional --> Hardcoded and should have import export option from GUI',
    DEFAULT_VALUE			INT	COMMENT 'DEFAULT_VALUE of the Signal --> Hardcoded and should have import export option from GUI',
    DISPLAY_TYPE			VARCHAR (255) COMMENT 'DISPLAY_TYPE of the Signal --> Hardcoded and should have import export option from GUI'
    
) COMMENT 'This table will store the details of FF Frames';

